-- GENERATED by scripts/generate-photo-migration.py - do not edit by hand.
-- Points products at real photos in S3 for 183 product types (4342 products).
-- Does nothing unless the Flyway placeholder imageBaseUrl (env var IMAGE_BASE_URL) is set to the bucket address.

CREATE TABLE tmp_photo_groups (folder VARCHAR(200) PRIMARY KEY);

-- The photo folder of every product: the 10 hand-written samples by SKU, the generated products by
-- category and product type (the name without its last two words, e.g. 'Webcam Pro 0001' -> 'webcam').
CREATE TABLE tmp_product_folder (product_id BIGINT PRIMARY KEY, folder VARCHAR(200) NOT NULL);
SELECT p.id,
       CASE p.sku_code
           WHEN 'APPLE-IP15P-128' THEN 'handwritten/iphone-15-pro'
           WHEN 'APPLE-MBP16-M3' THEN 'handwritten/macbook-pro-16'
           WHEN 'APPLE-APP2-WHT' THEN 'handwritten/airpods-pro-2'
           WHEN 'SAMSUNG-S24-256' THEN 'handwritten/samsung-galaxy-s24'
           WHEN 'SONY-WH1000XM5' THEN 'handwritten/sony-wh-1000xm5'
           WHEN 'DELL-XPS15-I9' THEN 'handwritten/dell-xps-15'
           WHEN 'APPLE-IPAD-AIR' THEN 'handwritten/ipad-air'
           WHEN 'AMAZON-KDL-PW' THEN 'handwritten/kindle-paperwhite'
           WHEN 'GOPRO-H12-BLK' THEN 'handwritten/gopro-hero-12'
           WHEN 'DYSON-V15-DETECT' THEN 'handwritten/dyson-v15'
           ELSE TRIM(BOTH '-' FROM REGEXP_REPLACE(LOWER(p.category), '[^a-z0-9]+', '-'))
                || '/' || TRIM(BOTH '-' FROM REGEXP_REPLACE(LOWER(REGEXP_REPLACE(p.name, ' [^ ]+ [^ ]+$', '')), '[^a-z0-9]+', '-'))
       END
FROM products p;

-- Keep only types that have photos, and nothing at all when no bucket address is configured.
DELETE FROM tmp_product_folder
WHERE LENGTH('${imageBaseUrl}') = 0 OR folder NOT IN (SELECT folder FROM tmp_photo_groups);

UPDATE product_images pi
SET url = TRIM(TRAILING '/' FROM '${imageBaseUrl}') || '/products/'
          || (SELECT f.folder FROM tmp_product_folder f WHERE f.product_id = pi.product_id)
          || '/' || pi.sort_order || '.jpg'
WHERE pi.product_id IN (SELECT product_id FROM tmp_product_folder);

UPDATE products p
SET image_url = (SELECT pi.url FROM product_images pi WHERE pi.product_id = p.id AND pi.sort_order = 1)
WHERE p.id IN (SELECT product_id FROM tmp_product_folder);

DROP TABLE tmp_product_folder;
DROP TABLE tmp_photo_groups;
